cat > next.config.ts <<'EOF'
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig
EOF
cat > components/request-metadata.tsx <<'EOF'
import { randomUUID } from 'node:crypto'
import { connection } from 'next/server'

export async function RequestMetadata() {
  // Defer to request time so these values are generated per request
  await connection()

  const generatedAt = new Date().toISOString()
  const sample = Math.random()
  const requestId = randomUUID()

  return (
    <aside>
      Request {requestId} generated at {generatedAt} (sample {sample})
    </aside>
  )
}
EOF
cat > app/layout.tsx <<'EOF'
import { Suspense, type ReactNode } from 'react'
import { RequestMetadata } from '@/components/request-metadata'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>
        <nav>Operations</nav>
        <Suspense fallback={<aside>Loading request details…</aside>}>
          <RequestMetadata />
        </Suspense>
        {children}
      </body>
    </html>
  )
}
EOF
